static inline void mrhiOutDiagnostic(
    mrhiDiagnostic* out, const mrhiDiagnostic* from)
{
    const mrhiDiagnostic value = *from;
    memset(out, 0, sizeof(*out));
    out->code = value.code;
    out->callsRefused = value.callsRefused;
}

static inline void mrhiOutInstanceNotification(
    mrhiInstanceNotification* out, const mrhiInstanceNotification* from)
{
    const mrhiInstanceNotification value = *from;
    memset(out, 0, sizeof(*out));
    out->kind = value.kind;
    out->request = value.request;
    out->outcome = value.outcome;
}

static inline void mrhiOutAdapterInfo(
    mrhiAdapterInfo* out, const mrhiAdapterInfo* from)
{
    const mrhiAdapterInfo value = *from;
    memset(out, 0, sizeof(*out));
    out->driver = value.driver;
    out->kind = value.kind;
    out->vendorId = value.vendorId;
    out->deviceId = value.deviceId;
    for (size_t i = 0; i < MRHI_ADAPTER_NAME_BYTES; ++i)
    {
        out->name[i] = value.name[i];
    }
    out->nameLength = value.nameLength;
}

